			function createPivotDs(rowDataRanged) {
			    var dsList = app.lookup("dsList");
			    var dsPivot = app.lookup("dsPivot");
			    
			    // 동적으로 생성한 데이터 셋 컬럼 삭제
			    var pvColNms = dsPivot.getColumnNames();
			    for (var i = 0; i < pvColNms.length; i++) {
			        if (pvColNms[i].substr(0, 4) == 'col_') {
			            dsPivot.deleteColumn(pvColNms[i]);
			        }
			    }
			    
			    var colNms = [{
			            "name": "RESRCE_NO"
			        },
			        {
			            "name": "BIZ_YR"
			        },
			        {
			            "name": "INST_NM"
			        },
			        {
			            "name": "SRVC_EXCN_BIZ_NM"
			        },
			        {
			            "name": "PVSN_RESRCE_NM"
			        },
			        {
			            "name": "EDU_PRD"
			        },
			        {
			            "name": "PIC_FLNM"
			        },
			        {
			            "name": "PIC_TELNO"
			        }
			    ];
			    var rowDatas = [];
			    
			    var eduCnt = 0;
			    
			    for (var idx = 0; idx < dsList.getRowCount(); idx++) {
			        var row = dsList.getRow(idx);
			        
			        var semstr = row.getValue("SEMSTR_SE_CD");
			        var eduRelm = row.getValue("EDU_PROGRM_SE_CD");
			        var goalOperSe = row.getValue("GOAL_OPER_SE");
			        
			        var colNm = "col_" + semstr + "_" + eduRelm + "_" + goalOperSe;
			        
			        if (row.getValue("RESRCE_NO") == dsList.getValue(0, "RESRCE_NO")) {
			            colNms.push({
			                "name": colNm
			            });
			            if (semstr == '00' && goalOperSe == '0') {
			                eduCnt++;
			            }
			        }
			        if (ValueUtil.isNull(dsList.getValue(idx + 1, "RESRCE_NO")) || row.getValue("RESRCE_NO") != dsList.getValue(idx + 1, "RESRCE_NO")) {
			            var rowData = {};
			            
			            rowData.RESRCE_NO = row.getValue("RESRCE_NO");
			            rowData.BIZ_YR = row.getValue("BIZ_YR");
			            rowData.INST_NM = row.getValue("INST_NM");
			            rowData.SRVC_EXCN_BIZ_NM = row.getValue("SRVC_EXCN_BIZ_NM");
			            rowData.PVSN_RESRCE_NM = row.getValue("PVSN_RESRCE_NM");
			            rowData.EDU_PRD = row.getValue("EDU_PRD");
			            rowData.PIC_FLNM = row.getValue("PIC_FLNM");
			            rowData.PIC_TELNO = row.getValue("PIC_TELNO");
			            for (var i = 0; i < colNms.length; i++) {
			                if (colNms[i].name.substr(0, 4) == "col_") {
			                    rowData[colNms[i].name] = dsList.findFirstRow("RESRCE_NO == \"" + row.getValue("RESRCE_NO") + "\" && SEMSTR_SE_CD == \"" + colNms[i].name.substr(4, 2) + "\" && EDU_PROGRM_SE_CD == \"" + colNms[i].name.substr(7, 2) + "\" && GOAL_OPER_SE == \"" + colNms[i].name.substr(10, 1) + "\"").getValue("OPER_HR_CNT");
			                }
			            }
			            
			            rowDatas.push(rowData);
			        }
			    };
			    
			    dsPivot.parseData({
			        "columns": colNms,
			        "rows": rowDatas
			    });
			    
			    return eduCnt;
			}

